const blockedWords=new Set(['mut','muti','mutin','mutra','mutrat','kar','kari','karin','karit','karen','pidh','pidhi','pidhin','pidhit','bythe','bytha','bythen','bythes','qij','qija','qije','qifsha','qifsh','qifni','qir','qirje','kurve','kurva','kurves','kurven','kurv','busht','bushter','bushteria','pirdh','pirdhu','pirdhni','ndyr','ndyresire','pis','pisllik','fuck','fucker','fuckers','fucking','fucked','motherfucker','motherfuckers','shit','shits','shitty','bullshit','horseshit','asshole','assholes','bitch','bitches','bitchy','bastard','bastards','dick','dicks','dickhead','cock','cocks','pussy','pussies','cunt','cunts','twat','slut','sluts','whore','whores','piss','pissed','crap','douche','douchebag','prick','pricks','damn','goddamn','hell','nigger','nigga','faggot','fag','retard','retarded']);
function containsProfanity(value){const normalized=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/0/g,'o').replace(/1/g,'i').replace(/3/g,'e').replace(/4/g,'a').replace(/5/g,'s').replace(/7/g,'t').replace(/@/g,'a').replace(/\$/g,'s');const tokens=normalized.split(/[^a-z0-9]+/).filter(Boolean);if(tokens.some(token=>blockedWords.has(token)))return true;for(const word of blockedWords){const letters=[...word].map(letter=>letter.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('[^a-z0-9\\s]{0,3}');if(new RegExp(`(^|[^a-z])${letters}($|[^a-z])`).test(normalized))return true}for(let start=0;start<tokens.length;start++){if(tokens[start].length!==1)continue;let joined='';for(let end=start;end<tokens.length&&end<start+16&&tokens[end].length===1;end++){joined+=tokens[end];if(joined.length>=3&&blockedWords.has(joined))return true}}return false}
