function blockRemaining(user){const until=Number(user?.profanityBlockedUntil)||0;if(until>Date.now())return until-Date.now();if(until&&until<=Date.now()){delete user.profanityBlockedUntil;user.profanityStrikes=0;try{saveUsers()}catch{}}return 0}
function blockNotice(user){const minutes=Math.max(1,Math.ceil(blockRemaining(user)/60000)),hours=Math.floor(minutes/60),left=minutes%60;return `Llogaria është bllokuar për 24 orë për shkak të përdorimit të gjuhës fyese. Provo sërish pas ${hours?`${hours} orë `:''}${left?`${left} min`:''}.`}
function currentUser(){const user=users.find(u=>u.email===currentEmail);if(user&&blockRemaining(user)){sessionStorage.removeItem('autopjese-session');currentEmail='';return null}return user}
function recordProfanityStrike(user){if(!user)return;user.profanityStrikes=(Number(user.profanityStrikes)||0)+1;if(user.profanityStrikes>=10){user.profanityBlockedUntil=Date.now()+24*60*60*1000;try{saveUsers()}catch{}sessionStorage.removeItem('autopjese-session');currentEmail='';renderAccount();closeModals();toast('Llogaria u bllokua për 24 orë pas 10 shkeljeve.');return true}try{saveUsers()}catch{}toast(`Gjuha fyese nuk lejohet. Paralajmërimi ${user.profanityStrikes}/10.`);return false}
function saveUsers(){localStorage.setItem(STORAGE.users,JSON.stringify(users))}
function detectDeviceLabel(){const ua=navigator.userAgent;let device=/iPhone|iPad|iPod/.test(ua)?'iPhone / iPad':/Android/.test(ua)?'Android':/Macintosh|Mac OS/.test(ua)?'Mac':/Windows/.test(ua)?'Windows':/Linux/.test(ua)?'Linux':'Shfletues';const browser=/Edg\//.test(ua)?'Edge':/Firefox\//.test(ua)?'Firefox':/Chrome\//.test(ua)?'Chrome':/Safari\//.test(ua)?'Safari':'shfletues';return `${device} · ${browser}`}
