function financeRangeStart(period=financePeriod,now=new Date()){const start=new Date(now);start.setHours(0,0,0,0);if(period==='week'){start.setDate(start.getDate()-6)}else if(period==='month'){start.setDate(1)}else if(period==='3months'){start.setDate(1);start.setMonth(start.getMonth()-2)}else if(period==='6months'){start.setDate(1);start.setMonth(start.getMonth()-5)}else if(period==='year'){start.setMonth(0,1)}return start}
