function normalize(s=''){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function compatibleWithVehicle(x){if(!vehicleFilter)return true;const aliases={'volkswagen':['volkswagen','vw'],'mercedesbenz':['mercedesbenz','mercedes'],'bmw':['bmw'],'audi':['audi'],'opel':['opel'],'toyota':['toyota'],'ford':['ford'],'renault':['renault'],'peugeot':['peugeot'],'skoda':['skoda']};const listingMake=normalize(x.make),wanted=normalize(vehicleFilter.make);if(listingMake!=='tedryshme'&&!(aliases[wanted]||[wanted]).some(a=>listingMake.includes(a)))return false;const wantedModel=normalize(vehicleFilter.model),listingFitment=normalize(`${x.model||''} ${x.title||''}`);if(wantedModel&&!listingFitment.includes(wantedModel))return false;if(vehicleFilter.year){const years=(String(x.model||'').match(/(?:19|20)\d{2}/g)||[]).map(Number);if(years.length>=2&&Number(vehicleFilter.year)<Math.min(...years)||years.length>=2&&Number(vehicleFilter.year)>Math.max(...years))return false;if(years.length===1&&Number(vehicleFilter.year)!==years[0])return false}return true}
const businessPromotionStorage='autopjese-business-promotion-requests';const businessPackagePostLimits={plus:30,premium:50,elite:100};
function activeBusinessPackage(email){const now=Date.now();return read(businessPromotionStorage,[]).filter(entry=>entry.sellerEmail===email&&entry.status==='active'&&entry.plan!=='free').sort((a,b)=>(b.activatedAt||b.created||0)-(a.activatedAt||a.created||0)).find(entry=>now<Number(entry.expiresAt||(entry.activatedAt||entry.created||now)+Number(entry.durationDays||30)*86400000))||null}
