function timeAgo(ts){const mins=Math.max(1,Math.floor((Date.now()-ts)/60000));if(mins<60)return `${mins} min më parë`;const h=Math.floor(mins/60);if(h<24)return `${h} orë më parë`;return `${Math.floor(h/24)} ditë më parë`}
