async function photoAsData(file){if(!file)return '';if(!file.type.startsWith('image/'))throw Error('Zgjidh një skedar fotografie.');if(file.size>8*1024*1024)throw Error('Fotografia duhet të jetë më e vogël se 8 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Fotografia nuk mund të lexohet.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('Fotografia nuk mund të hapet.'));img.onload=()=>{const scale=Math.min(1,1000/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78))};img.src=reader.result};reader.readAsDataURL(file)})}
