document.getElementById('profile-form').addEventListener('submit',e=>{e.preventDefault();const user=currentUser();if(!user)return;const data=new FormData(e.currentTarget),name=String(data.get('name')).trim(),phone=String(data.get('phone')).trim(),email=String(data.get('email')).trim().toLowerCase(),businessName=String(data.get('businessName')||'').trim(),error=document.getElementById('profile-error');error.textContent='';if(users.some(other=>other!==user&&other.email===email)){error.textContent='Ky email përdoret nga një llogari tjetër.';return}const oldEmail=user.email,oldName=user.name,location=String(data.get('location')||'').trim(),socials={instagram:String(data.get('socialInstagram')||'').trim(),facebook:String(data.get('socialFacebook')||'').trim(),tiktok:String(data.get('socialTikTok')||'').trim(),youtube:String(data.get('socialYouTube')||'').trim()},workHours={};for(const day of ['mon','tue','wed','thu','fri','sat','sun']){const closed=data.has(`scheduleClosed-${day}`),open=String(data.get(`scheduleOpen-${day}`)||''),close=String(data.get(`scheduleClose-${day}`)||'');if(!closed&&((open&&!close)||(!open&&close)||open&&close&&open>=close)){error.textContent='Plotëso të dy oraret ose shënoje ditën si të mbyllur; ora e mbylljes duhet të jetë më vonë.';return}if(closed||open&&close)workHours[day]=closed?{closed:true}:{open,close}}for(const url of Object.values(socials)){if(url){try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw new Error()}catch{error.textContent='Vendos një lidhje të vlefshme për rrjetet sociale.';return}}}user.name=name;user.phone=phone;user.location=location;user.email=email;user.socials=Object.fromEntries(Object.entries(socials).filter(([,url])=>url));if(Object.keys(workHours).length)user.workHours=workHours;else delete user.workHours;if(user.accountType==='business'){user.businessName=businessName;if(businessLogoDraft!==null){if(businessLogoDraft)user.businessLogo=businessLogoDraft;else delete user.businessLogo}}businessLogoDraft=null;if(profilePhotoDraft!==null){if(profilePhotoDraft)user.profilePhoto=profilePhotoDraft;else delete user.profilePhoto}profilePhotoDraft=null;listings=listings.map(item=>item.email===oldEmail?{...item,email,seller:item.seller===oldName?name:item.seller}:item);try{saveUsers();persist();sessionStorage.setItem('autopjese-session',email);currentEmail=email;renderAccount();toast('Të dhënat e llogarisë u përditësuan.');openAccountSettings()}catch{error.textContent='Ndryshimet nuk u ruajtën. Provo përsëri.'}});
