function openSaleInvoice(id){const item=listings.find(entry=>entry.id===id&&entry.email===currentEmail&&entry.status==='sold');if(!item)return;const user=currentUser(),sellerName=user?.accountType==='business'&&user.businessName?user.businessName:user?.name||item.seller||'Shitës',sellerLogo=user?.businessLogo||user?.profilePhoto;const soldAt=new Date(item.soldAt||item.created),invoiceNumber=item.invoiceNumber||`AP-${soldAt.getFullYear()}${String(soldAt.getMonth()+1).padStart(2,'0')}${String(soldAt.getDate()).padStart(2,'0')}-${String(item.id).slice(-5).toUpperCase()}`;item.invoiceNumber=invoiceNumber;persist();document.getElementById('invoice-email-form').hidden=false;document.getElementById('invoice-modal').dataset.invoiceType='sale';document.getElementById('simple-invoice-content').innerHTML=`<div class="invoice-brand"><img src="assets/logo-autopjese.png" alt="AUTOPJESA.NET"><span><b>AUTOPJESA.NET</b><small>Ndërmjetësim për shitje të pjesëve të makinave</small></span></div><div class="invoice-title-row"><div><span class="invoice-kicker">DËSHMI E SHITJES</span><h2 id="invoice-modal-title">Faturë e thjeshtë</h2></div><div class="invoice-number"><small>Numri i faturës</small><b>${safe(invoiceNumber)}</b></div></div><div class="invoice-parties"><div class="invoice-seller-panel"><small>Shitësi</small><div class="invoice-seller-identity"><span class="invoice-seller-logo">${sellerLogo?`<img src="${safe(sellerLogo)}" alt="${safe(sellerName)}">`:safe(String(sellerName).trim().split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase())}</span><b>${safe(sellerName)}</b></div>${user?.phone?`<span>${safe(user.phone)}</span>`:''}${user?.email?`<span>${safe(user.email)}</span>`:''}</div><div class="invoice-buyer-panel"><small>Klienti / blerësi</small><b>Nuk është regjistruar</b><span>Shitja u shënua nga shitësi.</span></div></div><table class="invoice-lines"><thead><tr><th>Përshkrimi</th><th>Sasia</th><th>Çmimi</th><th>Shuma</th></tr></thead><tbody><tr><td><b>${safe(item.title)}</b><small>${safe(item.category||'Pjesë makine')} · ${safe(item.condition||'')}</small></td><td>1</td><td>${fmt(item.price)}</td><td>${fmt(item.price)}</td></tr></tbody><tfoot><tr><td colspan="3">Totali</td><td>${fmt(item.price)}</td></tr></tfoot></table><div class="invoice-meta"><span><small>Data e shitjes</small><b>${soldAt.toLocaleDateString(window.getSiteLocale(),{dateStyle:'long'})}</b></span><span><small>Qyteti</small><b>${safe(item.city||'—')}</b></span></div><p class="invoice-disclaimer">Kjo është vetëm një faturë e thjeshtë / dëshmi e shitjes. <b>Nuk është kupon fiskal.</b></p><small class="invoice-footnote">Dokument i krijuar nga shitësi në platformën AUTOPJESA.NET.</small>`;document.getElementById('invoice-modal').dataset.invoiceId=item.id;document.getElementById('invoice-recipient-email').value=item.invoiceBuyerEmail||'';showModal('invoice-modal')}
