const productPremiumPrices={plus:{7:6.99,14:10.99,21:15.49,30:19.99},premium:{7:17.99,14:29.99,21:39.99,30:49.99},elite:{7:34.99,14:59.99,21:79.99,30:99.99}};function updateProductPremiumPrices(){const days=Number(document.querySelector('#product-premium-form [name=duration]').value)||30;document.querySelectorAll('[data-premium-price]').forEach(label=>{const price=productPremiumPrices[label.dataset.premiumPrice]?.[days];if(price!==undefined)label.textContent=new Intl.NumberFormat(window.getSiteLocale(),{style:'currency',currency:'EUR'}).format(price)})}document.querySelector('#product-premium-form [name=duration]').addEventListener('change',updateProductPremiumPrices);document.getElementById('language-toggle').addEventListener('click',updateProductPremiumPrices);updateProductPremiumPrices();function updatePremiumSubmitLabel(){const plan=document.querySelector('#product-premium-form [name=plan]:checked')?.value||'free',label=document.getElementById('product-premium-submit-label');if(label)label.textContent=plan==='free'?'Aktivizo falas':'Vazhdo me pagesën'}document.querySelectorAll('#product-premium-form [name=plan]').forEach(input=>input.addEventListener('change',updatePremiumSubmitLabel));updatePremiumSubmitLabel();
async function activatePaidPackageFromServer(paymentData){if(paymentData.status!=='paid')return false;const requests=read(businessPromotionStorage,[]),index=requests.findIndex(entry=>entry.id===paymentData.orderId||entry.serverOrderId===paymentData.orderId);if(index<0)return false;const item=requests[index];if(item.sellerEmail!==paymentData.sellerEmail)return false;const activatedAt=Number(paymentData.paidAt)||Date.now(),paymentReference=paymentData.reference||item.paymentReference,invoiceToken=String(paymentReference||paymentData.orderId).replace(/[^a-z\d]/gi,'').slice(-12).toUpperCase();requests[index]={...item,id:paymentData.orderId,status:'active',activatedAt,expiresAt:activatedAt+Number(paymentData.durationDays)*86400000,postLimit:Number(paymentData.postLimit)||businessPackagePostLimits[paymentData.plan]||0,priceEUR:Number(paymentData.amountCents)/100,paymentMethod:'card',paymentReference,invoiceNumber:item.invoiceNumber||`AP-PROMO-${invoiceToken}`,invoiceCreatedAt:activatedAt};localStorage.setItem(businessPromotionStorage,JSON.stringify(requests));if(currentUser()?.email===paymentData.sellerEmail){updateSellerPackageSummary();updateListingPackageLimit();renderListings()}return true}
async function fetchCardPaymentStatus(orderId,token){const response=await fetch(`/api/payments/status?orderId=${encodeURIComponent(orderId)}&token=${encodeURIComponent(token)}`,{cache:'no-store'});if(!response.ok)throw new Error('Pagesa nuk mund të kontrollohet.');return response.json()}
async function syncOutstandingCardPayments(){const user=currentUser();if(!user)return;const pending=read(businessPromotionStorage,[]).filter(entry=>entry.sellerEmail===user.email&&entry.paymentMethod==='card'&&entry.status!=='active'&&entry.serverOrderId&&entry.clientToken);let activated=false;for(const item of pending){try{const result=await fetchCardPaymentStatus(item.serverOrderId,item.clientToken);activated=await activatePaidPackageFromServer(result)||activated}catch{}}if(activated)toast('Pagesa u verifikua dhe pakoja u aktivizua.')}
async function handlePayseraReturn(){const params=new URLSearchParams(location.search),orderId=params.get('orderId'),token=params.get('token'),result=params.get('paymentResult');if(!orderId||!token||!result)return;if(result==='cancel'){toast('Pagesa me kartelë u anulua. Nuk u ngarkua asnjë shumë.');history.replaceState(null,'',location.pathname+location.hash);return}if(result!=='success')return;let confirmed=false;for(let attempt=0;attempt<10;attempt++){try{const resultData=await fetchCardPaymentStatus(orderId,token);if(resultData.status==='paid'){confirmed=await activatePaidPackageFromServer(resultData);break}if(resultData.status==='not_paid'){break}}catch{}await new Promise(resolve=>setTimeout(resolve,1500))}history.replaceState(null,'',location.pathname+location.hash);if(confirmed)toast('Pagesa me kartelë u verifikua. Pakoja promovuese është aktive.');else toast('Pagesa po verifikohet. Kontrollo statusin te Promovo llogarinë.')}
