const serviceCategory='Pajisje servisi',listingCategory=document.querySelector('#listing-form select[name="category"]'),listingMakeInput=document.querySelector('#listing-form [name="make"]');listingCategory.insertAdjacentHTML('beforeend',`<option value="${serviceCategory}">${serviceCategory}</option>`);listingCategory.parentElement.insertAdjacentHTML('beforeend','<small class="service-category-hint" hidden>P.sh. pajisje diagnostikuese, vegla, lift, kompresor ose pajisje pune për servis.</small>');document.querySelector('.filters').insertAdjacentHTML('beforeend',`<button class="filter-chip" data-filter="${serviceCategory}">Pajisje servisi</button>`);function updateServiceCategoryFields(){const isService=listingCategory.value===serviceCategory;listingMakeInput.required=!isService;listingMakeInput.placeholder=isService?'Opsionale · p.sh. Bosch':'p.sh. Volkswagen';listingMakeInput.parentElement.firstChild.textContent=isService?'Marka e pajisjes':'Marka e makinës';listingCategory.parentElement.querySelector('.service-category-hint').hidden=!isService}listingCategory.addEventListener('change',updateServiceCategoryFields);document.getElementById('listing-form').addEventListener('reset',()=>setTimeout(updateServiceCategoryFields,0));updateServiceCategoryFields();
