let aiAssistantStarted=false;
function appendAssistantMessage(role,text,results=[]){const log=document.getElementById('ai-assistant-messages'),message=document.createElement('div');message.className=`ai-message ${role==='user'?'is-user':'is-assistant'}`;message.innerHTML=`<p>${safe(text).replace(/\n/g,'<br>')}</p>${results.length?`<div class="ai-part-results">${results.map(item=>`<button type="button" data-ai-listing="${safe(item.id)}"><span><b>${safe(item.title)}</b><small>${safe(item.make)}${item.model?' · '+safe(item.model):''} · ${safe(item.city||'Kosovë')}</small></span><strong>${fmt(item.price)}</strong></button>`).join('')}</div>`:''}`;log.append(message);log.scrollTop=log.scrollHeight}
function startAIAssistant(){if(!aiAssistantStarted){appendAssistantMessage('assistant','Përshëndetje! Mund të të ndihmoj të gjesh pjesë në njoftime, të përdorësh faqen ose të kuptosh hapat fillestarë për një problem me makinën. Për të gjetur pjesën e duhur, më shkruaj markën, modelin dhe vitin.');aiAssistantStarted=true}showModal('ai-assistant-modal');requestAnimationFrame(()=>document.getElementById('ai-assistant-input').focus())}
function assistantReply(question){
 const n=normalize(question);
 if(!String(question||'').trim())return {text:'Shkruaj pyetjen tënde dhe do të përpiqem të të ndihmoj.'};
 if(/tym|flak|benzine|karburant|mbinxeh|temperatur|frena|pedali/.test(n)&&/tym|flak|ere|ndez|mbinxeh|temperatur|nukkap|nukpunoj|fund|dobet/.test(n))return {text:'Për siguri, ndalo në një vend të sigurt dhe mos vazhdo vozitjen nëse ka tym, erë karburanti, mbinxehje ose frenat nuk reagojnë normalisht. Fike motorin kur është e sigurt dhe kërko ndihmë nga mekaniku/servisi. Mos hap kapakun e sistemit të ftohjes kur motori është i nxehtë.'};
 if(/publiko|postim|njoftim/.test(n))return {text:'Për të publikuar pjesë, krijo llogari ose hyr, shtyp “Publiko pjesë”, plotëso titullin, kategorinë, gjendjen, çmimin për copë dhe sasinë në stok, pastaj ruaje njoftimin. Mund ta ndryshosh më vonë te “Postimet e mia”.'};
 if(/shporta|porosi|bler/.test(n))return {text:'Hap njoftimin e pjesës dhe shtoje në shportë. Aty mund të ndryshosh sasinë dhe të shohësh totalin. Kur dërgon kërkesën, shitësi mund të të përgjigjet në bisedat e faqes; pagesën dhe dorëzimin i konfirmoni drejtpërdrejt.'};
 if(/termin|montim|servis/.test(n))return {text:'Në njoftimet që ofrojnë montim, hap pjesën dhe shtyp “Kërko termin”. Për të gjetur servise pranë teje, përdor kutinë “Gjej auto servisin ose auto pjesën më të afërt” dhe lejo lokacionin ose zgjidh qytetin.'};
 if(/chat|bised/.test(n))return {text:'Hap njoftimin dhe shtyp “Bisedo në AUTOPJESA.NET” për t’i shkruar shitësit. Bisedat ruhen te menuja e llogarisë → “Mesazhet”.'};
 if(/fature|financa/.test(n))return {text:'Te llogaria hap “Financat” për të parë produktet e shënuara si të shitura, totalin dhe raportet sipas periudhës. Fatura e gjeneruar në këtë demo është dokument i thjeshtë, jo kupon fiskal.'};
 if(/regjistro|llogari/.test(n))return {text:'Shtyp “Llogaria”, zgjidh regjistrimin dhe plotëso emrin, llojin privat/biznes, telefonin, email-in dhe fjalëkalimin. Pastaj ndiq hapin e verifikimit.'};
 return {text:'Në AUTOPJESA.NET mund të kërkosh pjesë sipas emrit, markës ose modelit, të kontaktosh shitësin me chat dhe të publikosh pjesët e tua pasi të krijosh llogari. Më trego çfarë po përpiqesh të bësh dhe të udhëzoj.'};
}
const partGroups=[{terms:['alternator','gjenerator'],category:'Elektrike'},{terms:['frena','ferota','disqe frenash','kaliper','brake'],category:'Frena'},{terms:['fellne','felne','rim'],category:'Fellne'},{terms:['goma','pneumatike','tire','tyre'],category:'Goma'},{terms:['motor','engine','turbo'],category:'Motor'},{terms:['fener','llamba','drite','headlight'],category:'Ndriçim'},{terms:['pasqyre','parakolp','dere','karroceri'],category:'Karroceri'},{terms:['filter','filtra'],category:'Filtra'},{terms:['amortizator','susta','pezullim'],category:'Amortizatorë'}];
function assistantListingMatches(question){const n=normalize(question),group=partGroups.find(entry=>entry.terms.some(term=>n.includes(normalize(term))));let candidates=activeListingsForAssistant();if(group)candidates=candidates.filter(item=>item.category===group.category||group.terms.some(term=>normalize(`${item.title} ${item.category}`).includes(normalize(term))));const tokens=n.split(/(?=[a-z])(?=[^a-z])|[^a-z0-9]+/).filter(word=>word.length>2&&!['kerkoj','kerko','duhet','pjesa','pjese','makina','makines','per','kam','nga','nje','me','eshte','dua','please','need','part','parts','for','the','my','car'].includes(word));return candidates.map(item=>{const content=normalize(`${item.title} ${item.category} ${item.make} ${item.model} ${item.description}`),score=(group?3:0)+tokens.reduce((sum,word)=>sum+(content.includes(word)?1:0),0);return{item,score}}).filter(entry=>entry.score>0).sort((a,b)=>b.score-a.score||b.item.created-a.item.created).slice(0,4).map(entry=>entry.item)}
function activeListingsForAssistant(){return listings.filter(item=>item.status!=='sold'&&!containsProfanity(`${item.title} ${item.make} ${item.model} ${item.description}`))}
function assistantDiagnosis(question){const n=normalize(question),hasSymptom=/nuk|sht|ndiz|start|zhurm|noise|dridh|vibr|vibrat|tym|smoke|ere|temperatur|overheat|nxeh|drit|sinjal|frena|brake|pedal|rrjedh|rrjedhje|humb|problem|defekt|trokit|checkengine/.test(n);if(!hasSymptom)return null;if(/nukndiz|nukstart|notstart|wontstart|veshtirendiz|klik/.test(n))return 'Nëse makina nuk ndizet, shiko nëse dritat e panelit janë të dobëta dhe nëse dëgjohet klikim: bateria ose lidhjet e saj janë ndër shkaqet e zakonshme, por mund të jetë edhe motori i ndezjes ose furnizimi me karburant. Mos e provo vazhdimisht. Çfarë marke/modeli/viti është dhe çfarë dëgjon kur e ndez?';if(/frena|brake|pedal/.test(n))return 'Nëse pedali i frenave fundoset, frenimi dobësohet ose dëgjon fërkim metalik, mos e vozit makinën; kërko servis ose transport. Për zhurmë të lehtë, prapë duhet kontrolluar sistemi i frenimit sa më shpejt. Çfarë simptome vëren saktësisht?';if(/dridh|vibr|tim|rrot/.test(n))return 'Dridhja mund të vijë nga balancimi/gjendja e gomave, rrotat, pezullimi ose frenat. Nëse dridhja shtohet, timoni tërheq ose makina bëhet e vështirë për t’u kontrolluar, ndalo dhe kërko servis. A ndodh në një shpejtësi të caktuar apo kur frenon?';if(/temperatur|nxeh|mbinxeh|overheat/.test(n))return 'Nëse temperatura po rritet, ndalo në vend të sigurt dhe fik motorin. Mos e hap kapakun e radiatorit kur është i nxehtë. Prit të ftohet dhe kërko kontroll për rrjedhje, nivelin e ftohësit dhe sistemin e ftohjes; nëse përsëritet, mos vazhdo rrugën.';if(/tym|smoke|ere|flak/.test(n))return 'Tymi ose era e fortë mund të tregojnë problem serioz. Ndalo në vend të sigurt, fike motorin dhe largohu nëse sheh flakë ose tym të dendur. Mos vazhdo vozitjen; kontakto servis/ndihmë rrugore.';if(/zhurm|noise|trokit/.test(n))return 'Zhurmat mund të vijnë nga motori, rrotat, frenat ose pezullimi. Përshkruaj kur ndodh (në ndezje, gjatë kthesës, mbi gropa apo gjatë frenimit), nga cila anë vjen dhe markën/modelin/vitin e makinës që të të orientoj më saktë.';if(/checkengine|sinjal|drit/.test(n))return 'Drita “Check Engine” ka shumë shkaqe dhe nuk tregon vetë pjesën që duhet ndërruar. Një skanim OBD-II ndihmon të lexohet kodi. Nëse drita pulson, motori dridhet fort ose humb fuqi, ndalo sa më shpejt dhe kërko servis.';return 'Mund të të ndihmoj të kuptosh shkaqet e mundshme, por më duhen më shumë hollësi: marka, modeli, viti, simptoma dhe kur shfaqet. Nëse ka tym, mbinxehje ose problem me frenat, ndalo në vend të sigurt dhe kërko servis.'}
function getAssistantAnswer(question){const n=normalize(question);if(/website|faqja|autopjesa|llogari|regjistro|publiko|njoftim|shporta|porosi|chat|bised|termin|montim|fature|financa/.test(n))return assistantReply(question);const diagnostic=assistantDiagnosis(question);if(diagnostic)return{text:diagnostic};const matches=assistantListingMatches(question);if(matches.length)return{text:`Gjeta disa njoftime që mund të përputhen. Kontrollo modelin, vitin dhe specifikimet e pjesës para se ta porosisësh.`,listings:matches};return{text:'Mund të të ndihmoj me pjesë, mirëmbajtje dhe pyetje rreth makinës. Për kërkim pjese, shkruaj emrin, markën/modelin dhe vitin. Për problem, përshkruaj simptomën dhe kur shfaqet. P.sh. “alternator për Golf 6 2011” ose “dridhet kur frenoj”.'}}
