function carProfileFor(model){const m=normalize(model);if(['tiguan','x3','x5','glc','q5','kuga','rav4','captur','3008','kodiaq','tucson','sportage','sorento','crv','juke','qashqai','xtrail','cx5','xc60','xc90','500x','duster','ateca'].some(x=>m.includes(normalize(x))))return carProfiles.suv;if(['zafira','scenic','berlingo','alhambra','jogger'].some(x=>m.includes(normalize(x))))return carProfiles.mpv;const hatch=['golf','polo','seria1','aclass','a3','astra','corsa','yaris','clio','focus','fiesta','206','208','fabia','civic','jazz','i10','i20','i30','picanto','ceed','micra','mazda2','mazda3','v40','punto','500','c3','c4','sandero','ibiza','leon'].some(x=>m.includes(normalize(x)));return hatch?carProfiles.hatchback:carProfiles.sedan}
let vehiclePhotoRequest=0;
const vehiclePhotoCache=new Map();
async function findVehiclePhoto(make,model){const modelSearch=make==='BMW'?model.replace(/^Seria\s*/i,'')+' Series':model,query=`${make} ${modelSearch} car exterior`,params=new URLSearchParams({action:'query',generator:'search',gsrsearch:query,gsrnamespace:'6',gsrlimit:'20',prop:'imageinfo',iiprop:'url|size|mime',iiurlwidth:'1200',format:'json',origin:'*'}),response=await fetch(`https://commons.wikimedia.org/w/api.php?${params}`);if(!response.ok)throw Error('Kërkimi i fotografisë dështoi.');const result=await response.json(),pages=Object.values(result.query?.pages||{});const rejectWords=['logo','emblem','badge','wheel','engine','interior','toy','model car'];const modelKey=normalize(modelSearch),makeKey=normalize(make);const images=pages.map(page=>{const info=page.imageinfo?.[0];if(!info?.thumburl||!/^image\/(jpeg|png|webp)$/i.test(info.mime||'')||info.width<500||info.height<250)return null;const title=normalize(page.title),aspect=info.width/info.height;if(aspect<1.2||aspect>3.4||rejectWords.some(word=>title.includes(normalize(word))))return null;const score=(title.includes(modelKey)?8:0)+(title.includes(makeKey)?5:0)+(title.includes('exterior')?2:0)+(title.includes('front')?1:0);return{url:info.thumburl,source:info.descriptionurl||info.url,title:page.title,score}}).filter(Boolean).sort((a,b)=>b.score-a.score);return images[0]||null}
async function showVehiclePhoto(make,model){const request=++vehiclePhotoRequest,cacheKey=`${make}|${model}`,visual=document.querySelector('.car-visual'),photo=document.getElementById('car-photo'),credit=document.getElementById('photo-credit'),status=document.getElementById('photo-status'),svg=document.getElementById('car-illustration');const motionModes=['left','zoom','rise','right'],brandIndex=Math.max(0,Object.keys(vehicleModels).indexOf(make));visual.dataset.make=normalize(make);visual.dataset.motion=motionModes[brandIndex%motionModes.length];visual.classList.remove('has-photo','photo-error');visual.classList.add('photo-loading');photo.hidden=true;credit.hidden=true;status.hidden=false;status.textContent=`Po kërkohet fotografia e ${make} ${model}…`;svg.setAttribute('aria-hidden','true');try{let result=vehiclePhotoCache.get(cacheKey);if(result===undefined){result=await findVehiclePhoto(make,model);vehiclePhotoCache.set(cacheKey,result||null)}if(request!==vehiclePhotoRequest)return;if(!result)throw Error('Fotografia e këtij modeli nuk u gjet.');photo.alt=`${make} ${model}`;photo.onload=()=>{if(request!==vehiclePhotoRequest)return;visual.classList.remove('photo-loading','photo-error');visual.classList.add('has-photo');status.hidden=true;photo.hidden=false;credit.href=result.source;credit.title=result.title;credit.hidden=false};photo.onerror=()=>{if(request!==vehiclePhotoRequest)return;photo.hidden=true;visual.classList.remove('photo-loading','has-photo');visual.classList.add('photo-error');status.hidden=false;status.textContent=`Fotografia e ${make} ${model} nuk u hap. Provo sërish.`};photo.src=result.url}catch(error){if(request===vehiclePhotoRequest){visual.classList.remove('photo-loading','has-photo');visual.classList.add('photo-error');status.hidden=false;status.textContent=`Fotografia e ${make} ${model} nuk u gjet. Kontrollo lidhjen dhe provo sërish.`}}}
