function openAssistant(){showModal('assistant-modal');const field=document.querySelector('#assistant-form [name="question"]');setTimeout(()=>field.focus(),80)}
document.getElementById('assistant-launcher').addEventListener('click',openAssistant);
document.getElementById('assistant-form').addEventListener('submit',e=>{e.preventDefault();const field=e.currentTarget.elements.question,question=field.value.trim();if(!question)return;const user=currentUser();if(containsProfanity(question)){if(user)recordProfanityStrike(user);assistantAddMessage(assistantSay('Gjuha fyese nuk lejohet këtu. Shkruaje pyetjen pa fjalë fyese.','Offensive language is not allowed here. Please rephrase your question.'),'bot');field.value='';return}assistantAddMessage(question,'user');field.value='';const reply=assistantAnswer(question);setTimeout(()=>assistantAddMessage(reply,'bot'),320)});
document.getElementById('assistant-suggestions').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;const field=document.querySelector('#assistant-form [name="question"]');field.value=button.textContent;document.getElementById('assistant-form').requestSubmit()});
document.getElementById('assistant-messages').addEventListener('click',e=>{const button=e.target.closest('[data-assistant-listing]');if(button){closeModals();openDetail(button.dataset.assistantListing)}});
function showPaymentReview({user,plan,durationDays,price}){const planNames={plus:'Pako Plus',premium:'Pako Premium',elite:'Pako Elite'};document.getElementById('payment-review-business').textContent=user.businessName||user.name;document.getElementById('payment-review-plan').textContent=planNames[plan]||plan;document.getElementById('payment-review-duration').textContent=`${durationDays} ditë`;document.getElementById('payment-review-total').textContent=new Intl.NumberFormat(window.getSiteLocale(),{style:'currency',currency:'EUR'}).format(price);document.getElementById('payment-review-reference').textContent='—';document.getElementById('payment-reference-row').hidden=true;document.getElementById('payment-review-error').textContent='';document.getElementById('payment-review-status').textContent='Duke përgatitur pagesën…';const button=document.getElementById('payment-review-continue');button.disabled=true;button.dataset.paymentUrl='';showModal('payment-review-modal')}
document.getElementById('payment-review-back').addEventListener('click',()=>showModal('product-premium-modal'));
document.getElementById('payment-review-continue').addEventListener('click',e=>{const url=e.currentTarget.dataset.paymentUrl;if(url)window.location.assign(url)});
document.getElementById('product-premium-form').addEventListener('submit',async e=>{e.preventDefault();const user=currentUser(),data=new FormData(e.currentTarget),error=document.getElementById('product-premium-error'),submit=document.getElementById('product-premium-submit');if(!user){error.textContent='Hyr në llogari për të zgjedhur pakon.';return}const plan=String(data.get('plan')),durationDays=Number(data.get('duration'))||30;if(plan==='free'){error.textContent='Pakoja falas nuk sponsorizon llogarinë. Mund të vazhdosh me publikimet e zakonshme falas.';return}submit.disabled=true;error.textContent='';const price=productPremiumPrices[plan]?.[durationDays]??0;showPaymentReview({user,plan,durationDays,price});try{const response=await fetch('/api/payments/create',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({plan,durationDays,sellerEmail:user.email,sellerName:user.businessName||user.name})}),result=await response.json();if(!response.ok)throw new Error(result.message||'Pagesa me kartelë nuk është konfiguruar ende.');const id=result.orderId,request={id,serverOrderId:id,clientToken:result.clientToken,paymentReference:result.reference,scope:'seller-account',sellerEmail:user.email,sellerName:user.businessName||user.name,plan,priceEUR:price,durationDays,postLimit:businessPackagePostLimits[plan]||0,sponsored:true,paymentMethod:'card',status:'awaiting-card-checkout',created:Date.now()};const requests=read(businessPromotionStorage,[]);requests.push(request);localStorage.setItem(businessPromotionStorage,JSON.stringify(requests));document.getElementById('payment-review-reference').textContent=result.reference||id;document.getElementById('payment-reference-row').hidden=false;const continueButton=document.getElementById('payment-review-continue');continueButton.dataset.paymentUrl=result.paymentUrl;continueButton.disabled=false;document.getElementById('payment-review-status').textContent='Pagesa është gati. Vazhdo për të futur të dhënat e kartelës në faqen e sigurt të procesuesit.'}catch(error){document.getElementById('payment-review-status').textContent='Pagesa me kartelë nuk mund të niset tani.';document.getElementById('payment-review-error').textContent=error.message==='Failed to fetch'?'Serveri i pagesave nuk po përgjigjet. Provo përsëri pasi të jetë aktiv serveri i pagesave.':error.message||'Pagesa nuk mund të niset. Provo përsëri.'}finally{submit.disabled=false}});
renderAccount();renderListings();
